/*
 * Overwork — UI harness.
 *
 * Loads src/ui_overtake.js in a sandbox with the host globals mocked, drives
 * real input sequences, and checks what the UI does with them.
 *
 * The mock's get_param answers come from build/contract.json, generated by
 * test/dump_contract.c FROM THE ENGINE ITSELF. That matters: a mock written
 * from the UI's assumptions encodes the same misunderstanding twice and stays
 * green while the feature is broken on hardware — which is exactly how Mono
 * shipped a preset browser that never listed a file. The harness also fails if
 * the UI reads a key the engine does not serve, or writes one it does not
 * accept, so contract drift is caught rather than silently tolerated.
 *
 * Run via `make test`.
 */
import fs from 'fs';
import vm from 'vm';
import path from 'path';
import { fileURLToPath } from 'url';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');

const contract = JSON.parse(fs.readFileSync(path.join(root, 'build/contract.json'), 'utf8'));
const settable = new Set([...contract.settable, ...contract.commands]);

/* Where MIX sits on the GLOBAL page. Derived rather than written down, because
 * the page grew a third select and every hardcoded index after it shifted. */
const N_STAGES = (contract.get.effm || '0,0').split(',').length - 1;
const MIX_KNOB = N_STAGES;

/* Which machines each stage accepts, taken from the ENGINE's answer rather
 * than restated here. A second copy of this table is a copy that drifts, and
 * these tests exist precisely to catch the UI's copy drifting from it. */
const codes = (t) => (t || '').split(',').map(Number).filter(Number.isFinite);
const SRC_FAMILY = codes(contract.get.src_codes);
const FX_FAMILY  = codes(contract.get.fx_codes);
/* The key each stage's machine select answers to, stage-indexed. */
const STAGE_KEY  = ['src', 'fx1', 'fx2'];

/* Palette pads in reading order, minus undo/memo/song — the same order the UI
 * builds from PALETTE_PADS. Position N here holds family member N. */
const PALETTE_ORDER = [92, 93, 94, 95, 96, 97, 98, 99,
                       84, 85, 86, 87, 88, 89, 90, 91,
                       76, 77, 78, 79, 80];

let checks = 0;
let failures = 0;
function check(cond, msg) {
    checks++;
    if (!cond) { failures++; console.log(`  FAIL  ${msg}`); }
}

/* ------------------------------------------------------------- the mock */

/* Keys the engine serves as families — the fixture holds concrete instances,
 * so a request for lock12_3 is legal if lock<N>_<P> is a served family. */
const FAMILIES = [
    /^step\d+$/, /^locks\d+$/, /^lock\d+_\d+$/, /^locklabel\d+$/, /^prob\d+$/, /^trigtype\d+$/, /^song_row\d+$/
];

function familyServed(key) {
    if (!FAMILIES.some((re) => re.test(key))) return false;
    /* the family is served if the fixture holds at least one of its members */
    const shape = key.replace(/\d+/g, '#');
    return Object.keys(contract.get).some((k) => k.replace(/\d+/g, '#') === shape);
}

/* A virtual filesystem implementing QuickJS's REAL contracts, copied from
 * schwung's own preset browser and the C source — never from the code under
 * test. The two that bite:
 *   os.readdir  -> [names, errno] TUPLE, and names includes "." and ".."
 *   os.rename / os.remove -> return 0 or -errno, and NEVER throw
 * Host file bindings are separate and DO return booleans. */
function makeVFS() {
    const files = new Map();
    const binaries = new Map();     /* path -> Uint8Array, for base64 reads */
    const dirs = new Set();
    let renameFails = false;

    return {
        files, dirs, binaries,
        failRenames(v) { renameFails = v; },

        readdir(path) {
            /* A file is not a directory: the real os.readdir answers ENOTDIR,
             * which is how the recursive sample scan terminates. Answering
             * ENOENT instead would hide a walk that never bottoms out. */
            if (files.has(path) || binaries.has(path)) return [[], 20];
            if (!dirs.has(path)) return [[], 2];            /* ENOENT */
            const names = ['.', '..'];                       /* real listings carry these */
            /* Child DIRECTORIES as well as files — without them the mock
             * cannot represent a tree, and a recursive walk has nothing to
             * descend into, which looks exactly like a broken walk. */
            for (const f of [...files.keys(), ...binaries.keys(), ...dirs]) {
                if (f.startsWith(path + '/')) {
                    const rest = f.slice(path.length + 1);
                    if (!rest.includes('/') && !names.includes(rest)) names.push(rest);
                }
            }
            return [names, 0];
        },
        rename(a, b) {
            if (renameFails) return -1;
            if (!files.has(a)) return -2;
            files.set(b, files.get(a));
            files.delete(a);
            return 0;
        },
        remove(p) {
            if (!files.has(p)) return -2;
            files.delete(p);
            return 0;
        },
        mkdir(p) { dirs.add(p); return 0; }
    };
}

function makeHost() {
    const store = Object.assign({}, contract.get);
    const writes = [];
    const reads = [];
    const unknownReads = new Set();
    const unknownWrites = new Set();
    const leds = new Map();
    const screen = [];
    const roundTrips = [];   /* one entry per blocking read of the DSP */
    let shiftState = 0;

    const vfs = makeVFS();

    const host = {
        __vfs: vfs,
        /* Host file bindings return booleans / string-or-null — a DIFFERENT
         * contract from the os.* calls above. */
        host_write_file(path, data) {
            const dir = path.slice(0, path.lastIndexOf('/'));
            if (!vfs.dirs.has(dir)) return false;
            vfs.files.set(path, String(data));
            return true;
        },
        host_read_file(path) {
            return vfs.files.has(path) ? vfs.files.get(path) : null;
        },
        /* Binary-safe read. host_read_file returns a C string and stops at the
         * first NUL, which in a WAV is usually inside the header — that is why
         * the loader uses this one. */
        host_read_file_base64(path) {
            const raw = vfs.binaries.get(path);
            if (!raw) return null;
            return Buffer.from(raw).toString('base64');
        },
        host_ensure_dir(path) { vfs.dirs.add(path); return true; },
        /* The shim is authoritative for SHIFT. Tracking it locally from CC 49
         * latches when a release is missed, and on hardware that made a knob
         * edit the base value instead of writing a lock. */
        shadow_get_shift_held() { return shiftState; },
        host_flush_display() {},

        /* Every one of these is a blocking round-trip on hardware, serviced
         * once per SPI frame. Counting them is the point — a UI that is
         * "correct" but takes sixty frames to redraw is broken on the Move. */
        host_module_get_param(key) {
            roundTrips.push({ bulk: false, keys: [key] });
            reads.push(key);
            /* work_get_param("state") appends the recorded sample path when
             * there is one. Modelling only the PARSE side and not this one is
             * how a save that silently drops the path still passes. */
            if (key === 'state' && store.sample_path) {
                const esc = `${store.sample_path}`.replace(/([\\"])/g, '\\$1');
                return `${store.state}`.replace(/\}\s*$/, `,"smp":"${esc}"}`);
            }
            if (key in store) return store[key];
            if (familyServed(key)) {
                /* a member the fixture did not capture: answer the way the
                 * engine does for an untouched step */
                if (/^lock\d+_\d+$/.test(key)) return '-1';
                if (/^step\d+$/.test(key)) return '0:0:0:0:0';
                if (/^locks\d+$/.test(key)) return '';
                if (/^locklabel\d+$/.test(key)) return '?';
            }
            unknownReads.add(key);
            return null;
        },
        /* BULK_GET, transcribed from shim_handle_param_bulk / bulk_next in
         * schwung's src/schwung_shim.c — NOT from the code under test. The
         * request is "<count>\n" then count records of "<len>\n<key>"; the
         * response is the same shape carrying values, and a key the DSP does
         * not answer comes back as a zero-length record rather than being
         * omitted. The shim refuses more than 64 items outright. */
        host_module_get_params(blob) {
            const s = `${blob}`;
            let p = 0;
            const readLen = () => {
                let n = 0, any = false;
                while (p < s.length && s[p] >= '0' && s[p] <= '9') {
                    n = n * 10 + (s.charCodeAt(p) - 48); p++; any = true;
                }
                if (!any || s[p] !== '\n') return -1;
                p++;
                return n;
            };
            const count = readLen();
            if (count < 0) return null;
            if (count > 64) return null;              /* SHADOW_BULK_MAX_ITEMS */
            const keys = [];
            for (let i = 0; i < count; i++) {
                const len = readLen();
                if (len < 0) return null;
                keys.push(s.slice(p, p + len));
                p += len;
            }
            roundTrips.push({ bulk: true, keys });
            let out = `${keys.length}\n`;
            for (const k of keys) {
                reads.push(k);
                let v = null;
                if (k in store) v = store[k];
                else if (familyServed(k)) {
                    if (/^lock\d+_\d+$/.test(k)) v = '-1';
                    else if (/^step\d+$/.test(k)) v = '0:0:0:0:0';
                    else if (/^locks\d+$/.test(k)) v = '';
                    else if (/^locklabel\d+$/.test(k)) v = '?';
                }
                if (v === null) { unknownReads.add(k); v = ''; }
                out += `${`${v}`.length}\n${v}`;
            }
            return out;
        },
        setShift(v) { shiftState = v ? 1 : 0; },
        host_module_set_param(key, val) {
            writes.push({ key, val });
            /* Model the sample transfer the way work_core.c does, so
             * sample_frames/sample_name read back the way the engine reports
             * them. Without this the mock records the writes and answers the
             * fixture's stale values, and a UI that correctly asks the ENGINE
             * what landed looks broken. */
            if (key === 'sample_begin') {
                const [n, nm] = `${val}`.split(':');
                store.__declared = parseInt(n, 10) || 0;
                store.__pending = nm || '';
                store.__fill = 0;
            } else if (key === 'sample_chunk') {
                const bytes = Buffer.from(`${val}`, 'base64').length;
                store.__fill = (store.__fill || 0) + Math.floor(bytes / 4);
            } else if (key === 'sample_end') {
                const n = Math.min(store.__fill || 0, store.__declared || 0);
                store.sample_frames = `${n}`;
                store.sample_name = n > 0 ? (store.__pending || '') : '';
            } else if (key === 'sample_clear') {
                store.sample_frames = '0';
                store.sample_name = '';
                store.sample_path = '';
            } else if (key === 'state') {
                /* apply_state parses the recorded sample path back out of the
                 * blob. Modelling it here is what lets a preset-load test see
                 * what the engine would actually hand back — without it the
                 * mock answers the fixture's stale path and a UI that
                 * correctly reloads the audio looks like it did nothing. */
                const m = /"smp":"((?:[^"\\]|\\.)*)"/.exec(`${val}`);
                if (m) store.sample_path = m[1].replace(/\\(.)/g, '$1');
            }
            const fam = key.replace(/\d+/g, '#');
            const known = settable.has(key)
                || [...settable].some((s) => s.replace(/\d+/g, '#') === fam);
            if (!known) unknownWrites.add(key);
            store[key] = `${val}`;
        },
        setLED(note, color) { leds.set(note, color); },
        setButtonLED(cc, color) { leds.set(`cc${cc}`, color); },
        clear_screen() { screen.length = 0; },
        print(x, y, text) { screen.push({ x, y, text }); },
        fill_rect() {},
        draw_rect() {},
        text_width(t) { return String(t).length * 5; },
        move_midi_internal_send() {},
        Date,
        Math,
        Number,
        JSON,
        String,
        Array,
        parseInt,
        parseFloat,
        isFinite,
        console
    };
    host.globalThis = host;
    /* What the screen reader was told. Some views draw a status the user sees
     * and others only speak it, so a test that checks the screen alone cannot
     * tell "nothing happened" from "it told you, elsewhere". */
    const spoken = [];
    host.__spoken = spoken;
    return { host, vfs, writes, reads, roundTrips, unknownReads, unknownWrites,
             leds, screen, store, spoken };
}

/* Stub the three schwung shared modules the UI imports. */
const STUBS = {
    '/data/UserData/schwung/shared/constants.mjs': `
        export const MoveKnob1 = 71, MoveShift = 49, MoveMainButton = 3, MoveMainKnob = 14;
        export const Black=0, White=120, LightGrey=118, DarkGrey=124, Red=127, BrightRed=1;
        export const Blue=125, Green=126, BrightGreen=8, Cyan=14, Purple=22, SkyBlue=47;
        export const Lime=31, OrangeRed=2, BurntOrange=28, YellowGreen=30, TealGreen=12, Rose=24;
    `,
    '/data/UserData/schwung/shared/input_filter.mjs': `
        export function decodeDelta(v){ if(v===0) return 0; if(v>=1&&v<=63) return v; if(v>=65&&v<=127) return -(128-v); return 0; }
        export function shouldFilterMessage(d){ const st=d[0], t=st&0xF0;
            if(st===0xF8||st===0xF0||st===0xF7) return true;
            if(t===0xD0||t===0xA0) return true;
            if((t===0x90||t===0x80)&&d[1]<10) return true;
            return false; }
        export function setLED(n,c,f){ globalThis.setLED(n,c,f); }
        export function setButtonLED(n,c,f){ globalThis.setButtonLED(n,c,f); }
    `,
    '/data/UserData/schwung/shared/screen_reader.mjs': `
        export function announce(t){ globalThis.__spoken.push(String(t)); }
        export function announceParameter(t){ globalThis.__spoken.push(String(t)); }
        export function announceView(t){ globalThis.__spoken.push(String(t)); }
    `,
    'os': `
        export function readdir(p){ return globalThis.__vfs.readdir(p); }
        export function rename(a,b){ return globalThis.__vfs.rename(a,b); }
        export function remove(p){ return globalThis.__vfs.remove(p); }
        export function mkdir(p){ return globalThis.__vfs.mkdir(p); }
    `
};

async function loadUI() {
    const ctx = makeHost();
    const context = vm.createContext(ctx.host);
    const src = fs.readFileSync(path.join(root, 'src/ui_overtake.js'), 'utf8');

    const mod = new vm.SourceTextModule(src, { context, identifier: 'ui_overtake.js' });
    await mod.link(async (spec) => {
        const code = STUBS[spec];
        if (!code) throw new Error(`unexpected import: ${spec}`);
        const m = new vm.SourceTextModule(code, { context, identifier: spec });
        await m.link(() => { throw new Error('nested import'); });
        return m;
    });
    await mod.evaluate();
    return ctx;
}

/* MIDI helpers matching what the shim delivers */
const cc   = (num, val) => [0xB0, num, val];
/* Injecting CC 49 alone is no longer enough: the UI asks the shim. Tests that
 * hold Shift must move the shim's view too, which is what the hardware does. */
function holdShift(ctx, on) {
    /* Tick past the post-init settling window first. The UI ignores Shift for
     * about a second after init, because the launch gesture is itself a Shift
     * combo whose release is swallowed while init runs — so a module that
     * trusted the flag started life latched. A real user cannot press Shift in
     * the same millisecond they opened the module; the harness should not
     * either. */
    for (let i = 0; i < 50; i++) ctx.host.tick();
    ctx.host.setShift(on);
    ctx.host.onMidiMessageInternal(cc(49, on ? 127 : 0));
}
/* Move's step buttons are NOTES 16-31, not CCs. The harness sent them as CCs,
 * which is why every step-related check passed while the sequencer could not
 * be played on hardware at all — the mock encoded my assumption instead of the
 * device's contract. Confirmed from the device log: status=144 d1=20 d2=127.
 * schwung's hardware notes: "Pads notes 68-99. Steps notes 16-31." */
const step     = (n, val) => [0x90, 16 + n, val];
const stepDown = (n) => step(n, 127);
const stepUp   = (n) => step(n, 0);
const noteOn  = (n) => [0x90, n, 127];
const noteOff = (n) => [0x80, n, 0];

const KNOB1 = 71, JOG = 14, SHIFT = 49, STEP1 = 16, JOG_CLICK = 3;

/* --------------------------------------------------------------- tests */

async function testInitReadsOnlyServedKeys() {
    console.log('init reads only keys the engine serves');
    const ctx = await loadUI();
    ctx.host.init();
    check(ctx.unknownReads.size === 0,
          `UI read keys the engine does not serve: ${[...ctx.unknownReads].join(', ')}`);
    check(ctx.reads.includes('machines'), 'UI never asked for the machine list');
    check(ctx.reads.includes('labels_src'), 'UI never asked for the SRC stage knob labels');
    check(ctx.reads.includes('src_codes') && ctx.reads.includes('fx_codes'),
          'UI never asked the engine which machines each stage accepts');
    check(ctx.screen.length > 0, 'init drew nothing to the screen');
    check(ctx.leds.size > 20, `init painted only ${ctx.leds.size} LEDs`);
}

/* The headline gesture. Holding a step and turning a knob must write a
 * lock<step>_<param> key — not the base parameter. */
async function testHoldStepPlusKnobLocks() {
    console.log('hold a step + turn a knob writes a parameter lock');
    const ctx = await loadUI();
    ctx.host.init();
    ctx.writes.length = 0;

    ctx.host.onMidiMessageInternal(stepDown(2));   /* hold step 3 */
    ctx.host.onMidiMessageInternal(cc(KNOB1, 1));         /* knob 1, +1  */

    const lockWrites = ctx.writes.filter((w) => /^lock\d+_\d+$/.test(w.key));
    check(lockWrites.length === 1,
          `expected one lock write, got ${JSON.stringify(ctx.writes)}`);
    if (lockWrites.length) {
        check(lockWrites[0].key === 'lock2_0',
              `expected lock2_0 (step 3, SRC knob A), got ${lockWrites[0].key}`);
    }
    const baseWrites = ctx.writes.filter((w) => /^(src|fx\d)_p\d$/.test(w.key));
    check(baseWrites.length === 0,
          `the base parameter must not move while locking, got ${JSON.stringify(baseWrites)}`);

    /* releasing after a lock must NOT also toggle the trig off */
    ctx.writes.length = 0;
    ctx.host.onMidiMessageInternal(stepUp(2));
    const stepWrites = ctx.writes.filter((w) => /^step\d+$/.test(w.key));
    check(stepWrites.length === 0,
          `release after locking should not rewrite the step, got ${JSON.stringify(stepWrites)}`);
}

/* The v2 lock map is CONTIGUOUS across the stages: SRC at 0-7, FX 1 at 8-15,
 * FX 2 at 16-23, then the three machine selects. Get this wrong and holding a
 * step while turning a knob on FX 2 writes a lock onto a machine select — the
 * patch would change machine mid-pattern and nothing would say why. */
async function testLastStageLocksAppendRatherThanCollide() {
    console.log("FX 2's locks land at 16-23, below the machine selects");
    const ctx = await loadUI();
    ctx.host.init();

    /* focus FX 2: the stage pad cycles SRC -> FX 1 -> FX 2 */
    for (let i = 0; i < 2; i++) {
        ctx.host.onMidiMessageInternal(noteOn(70));
        ctx.host.onMidiMessageInternal(noteOff(70));
    }
    ctx.host.tick();

    ctx.writes.length = 0;
    ctx.host.onMidiMessageInternal(stepDown(2));          /* hold step 3 */
    ctx.host.onMidiMessageInternal(cc(KNOB1, 1));         /* knob 1, +1  */

    const locks = ctx.writes.filter((w) => /^lock\d+_\d+$/.test(w.key));
    check(locks.length === 1,
          `expected one lock write, got ${JSON.stringify(ctx.writes)}`);
    if (locks.length) {
        check(locks[0].key === 'lock2_16',
              `FX 2 knob A must lock index 16, got ${locks[0].key} — 24 is ` +
              `the SRC machine select, so an off-by-map here silently ` +
              `changes machine mid-pattern`);
    }
    ctx.host.onMidiMessageInternal(stepUp(2));

    /* and the knob edits FX 2's base parameter, not SRC's */
    ctx.writes.length = 0;
    ctx.host.onMidiMessageInternal(cc(KNOB1, 1));
    const base = ctx.writes.filter((w) => /^(src|fx\d)_p\d$/.test(w.key));
    check(base.length === 1 && base[0].key === 'fx2_p1',
          `knob 1 with FX 2 focused wrote ${JSON.stringify(base)}, expected fx2_p1`);
}

/* Nudging an existing lock must start from the LOCK's value, not the base —
 * this is what the missing lock<N>_<P> getter used to break. */
async function testLockNudgeStartsFromLock() {
    console.log('nudging an existing lock continues from the locked value');
    const ctx = await loadUI();
    ctx.host.init();

    /* step 4 (index 3) has lock 0 = 100 in the fixture; base fx1_p1 is 76 */
    ctx.writes.length = 0;
    ctx.host.onMidiMessageInternal(stepDown(3));
    ctx.host.onMidiMessageInternal(cc(KNOB1, 1));

    const w = ctx.writes.find((x) => x.key === 'lock3_0');
    check(!!w, 'no write to lock3_0');
    if (w) {
        check(`${w.val}` === '101',
              `expected 101 (locked 100 + 1), got ${w.val} — the UI fell back to the base value`);
    }
}

async function testPlainTapTogglesTrig() {
    console.log('tapping a step with no edit toggles its trig');
    const ctx = await loadUI();
    ctx.host.init();
    ctx.writes.length = 0;

    ctx.host.onMidiMessageInternal(stepDown(5));
    ctx.host.onMidiMessageInternal(stepUp(5));

    const stepWrites = ctx.writes.filter((w) => /^step\d+$/.test(w.key));
    check(stepWrites.length === 1, `expected one step write, got ${stepWrites.length}`);
    if (stepWrites.length) {
        check(stepWrites[0].key === 'step5', `expected step5, got ${stepWrites[0].key}`);
        check(/^1:/.test(stepWrites[0].val),
              `empty step should turn on, got ${stepWrites[0].val}`);
    }
}

async function testShiftEscapesTheLockGesture() {
    console.log('shift + knob edits the base value even while a step is held');
    const ctx = await loadUI();
    ctx.host.init();
    ctx.writes.length = 0;

    ctx.host.onMidiMessageInternal(stepDown(2));
    holdShift(ctx, true);
    ctx.host.onMidiMessageInternal(cc(KNOB1, 1));

    const lockWrites = ctx.writes.filter((w) => /^lock\d+_\d+$/.test(w.key));
    const baseWrites = ctx.writes.filter((w) => /^(src|fx\d)_p\d$/.test(w.key));
    check(lockWrites.length === 0, 'shift + knob must not create a lock');
    check(baseWrites.length === 1,
          `shift + knob should edit the base, got ${JSON.stringify(ctx.writes)}`);
}

async function testMachinePaletteLoadsMachines() {
    console.log('palette pads load machines into the focused stage');
    const ctx = await loadUI();
    ctx.host.init();
    ctx.writes.length = 0;

    ctx.host.onMidiMessageInternal(noteOn(92));           /* palette index 0 */
    ctx.host.onMidiMessageInternal(noteOff(92));
    let w = ctx.writes.find((x) => x.key === 'src');
    check(!!w && `${w.val}` === `${SRC_FAMILY[0]}`,
          `pad 92 should load source ${SRC_FAMILY[0]} into SRC, got ${w && w.val}`);

    /* focus the next stage, then load again. The palette is a different FAMILY
     * now, so the same pad position means a different machine. */
    ctx.writes.length = 0;
    ctx.host.onMidiMessageInternal(noteOn(70));           /* PAD_STAGE */
    ctx.host.onMidiMessageInternal(noteOff(70));
    ctx.host.onMidiMessageInternal(noteOn(99));           /* palette index 7 */
    ctx.host.onMidiMessageInternal(noteOff(99));
    w = ctx.writes.find((x) => x.key === 'fx1');
    check(!!w && `${w.val}` === `${FX_FAMILY[7]}`,
          `pad 99 should load effect ${FX_FAMILY[7]} into FX 1, got ${w && w.val}`);
}

/* The SRC stage takes six machines and the pads offer twenty-one positions.
 * The fifteen spare pads must be DEAD, not wrap around or load an effect the
 * engine would refuse — a pad that silently does nothing is a small confusion,
 * a pad that loads a reverb into the source stage is a broken patch. */
async function testPaletteRefusesOutOfFamilyPads() {
    console.log('palette pads past the focused stage\'s family are dead');
    const ctx = await loadUI();
    ctx.host.init();
    ctx.writes.length = 0;

    /* SRC is focused at init. Palette position 7 is past the six sources. */
    ctx.host.onMidiMessageInternal(noteOn(99));
    ctx.host.onMidiMessageInternal(noteOff(99));
    check(!ctx.writes.some((x) => x.key === 'src'),
          `a pad past the source family loaded something: ${JSON.stringify(ctx.writes)}`);

    /* And it is dark rather than left showing the previous stage's machine. */
    ctx.host.tick();
    check(ctx.leds.get(99) === 0,
          `pad 99 should be dark on the SRC stage, got ${ctx.leds.get(99)}`);
}

