async function testNoUnknownWritesAnywhere() {
    console.log('every key the UI writes is one the engine accepts');
    const ctx = await loadUI();
    ctx.host.init();

    /* exercise a broad slice of the surface */
    for (const pad of [68, 69, 70, 71, 72, 73, 74, 80, 81, 82, 83, 92, 95, 99]) {
        ctx.host.onMidiMessageInternal(noteOn(pad));
        ctx.host.onMidiMessageInternal(noteOff(pad));
    }
    for (let s = 0; s < 16; s++) {
        ctx.host.onMidiMessageInternal(cc(STEP1 + s, 127));
        ctx.host.onMidiMessageInternal(cc(KNOB1 + (s % 8), 1));
        ctx.host.onMidiMessageInternal(cc(JOG, 1));
        ctx.host.onMidiMessageInternal(cc(STEP1 + s, 0));
    }
    for (let i = 0; i < 40; i++) ctx.host.tick();

    check(ctx.unknownWrites.size === 0,
          `UI wrote keys the engine does not accept: ${[...ctx.unknownWrites].join(', ')}`);
    check(ctx.unknownReads.size === 0,
          `UI read keys the engine does not serve: ${[...ctx.unknownReads].join(', ')}`);
}

/* A suspended overtake session resumes with its LEDs cleared; one paintAll is
 * ~60 writes in a tick and the shim's queue drops some. Overwork must force
 * several spaced repaints (the Smack v0.9.1 fix). */
async function testResumeForcesRepaints() {
    console.log('resume forces repeated full LED repaints');
    const ctx = await loadUI();
    ctx.host.init();

    ctx.leds.clear();
    ctx.host.onResume();
    check(ctx.leds.size > 20, `onResume painted only ${ctx.leds.size} LEDs`);

    let repaints = 0;
    for (let i = 0; i < 40; i++) {
        ctx.leds.clear();
        ctx.host.tick();
        if (ctx.leds.size > 20) repaints++;
    }
    check(repaints >= 3, `expected at least 3 forced repaints after resume, saw ${repaints}`);
}

