/* Knob response has now been wrong in BOTH directions on hardware, so this
 * pins the exact numbers rather than a range.
 *
 * decodeDelta returns ACCUMULATED movement — up to 63 from one event. Applied
 * raw to the 21-entry machine select it hit an end stop every time ("fx 2 only
 * does warble or bypass"); clamped to one step per event, crossing the list
 * took twenty separate clicks ("super slow"). The rule is a cap of a quarter
 * of the range: one detent moves one, a full-speed spin moves ceil(span/4). */
/* Walk the edit pages until the machine selects are on screen, rather than
 * pressing a fixed number of times. A count here breaks whenever a page is
 * added between FX and GLOBAL — which is what adding the voice-filter page
 * did to six tests at once. */
async function gotoGlobalPage(ctx) {
    for (let i = 0; i < 12; i++) {
        ctx.host.tick();
        if (ctx.screen.some((x) => /GLOBAL/.test(x.text))) return;
        ctx.host.onMidiMessageInternal(noteOn(72));
        ctx.host.onMidiMessageInternal(noteOff(72));
    }
    ctx.host.tick();
    throw new Error('never reached the GLOBAL edit page: ' +
                    JSON.stringify(ctx.screen.map((x) => x.text)));
}

/* Start the UI with a chosen value already in the DSP, on the GLOBAL page.
 * The value has to be in the store BEFORE init — the UI mirrors the DSP at
 * load, and deliberately does not re-read on every knob event. */
async function atGlobalWith(seed) {
    const ctx = await loadUI();
    Object.assign(ctx.store, seed);
    ctx.host.init();
    await gotoGlobalPage(ctx);
    ctx.writes.length = 0;
    return ctx;
}

/* A machine knob steps through its stage's FAMILY, so both the acceleration
 * cap and the end stops come from that family's length — not from the length of
 * the whole machine list. Both families are checked because they are very
 * different sizes (six sources, twenty-one effects) and the cap arithmetic is
 * where an off-by-one would hide. */
async function stepMachineKnob(stage, fam, fromPos, delta) {
    const seed = {};
    seed[STAGE_KEY[stage]] = `${fam[fromPos]}`;
    const ctx = await atGlobalWith(seed);
    ctx.host.onMidiMessageInternal(cc(KNOB1 + stage, delta));
    const w = ctx.writes.find((x) => x.key === STAGE_KEY[stage]);
    return w ? parseInt(`${w.val}`, 10) : null;
}

async function testKnobResponseCurve() {
    console.log('knob response: one detent moves one, a fast spin moves a quarter of the range');

    for (const [stage, fam, name] of [[0, SRC_FAMILY, 'SRC'], [1, FX_FAMILY, 'FX 1']]) {
        const cap = Math.ceil((fam.length - 1) / 4);

        let got = await stepMachineKnob(stage, fam, 1, 1);        /* one detent */
        check(got === fam[2],
              `${name}: one detent moved to ${got} — expected ${fam[2]}, the next ` +
              `machine in the family rather than the next machine CODE`);

        got = await stepMachineKnob(stage, fam, 1, 25);           /* full-speed spin */
        check(got === fam[1 + cap],
              `${name}: a 25-detent event moved to ${got} — expected ${fam[1 + cap]}: ` +
              `neither an end stop nor a single step`);

        /* the end of each family must be REACHABLE — Granulator was excluded
         * when this range was a hardcoded constant */
        got = await stepMachineKnob(stage, fam, fam.length - 2, 40);
        check(got === fam[fam.length - 1],
              `${name}: could not reach the last machine in the family ` +
              `(${fam[fam.length - 1]}); got ${got}`);
    }

    /* wide ranges keep the acceleration, or 0-127 becomes unusable */
    const ctx = await atGlobalWith({ mix: '40' });
    ctx.host.onMidiMessageInternal(cc(KNOB1 + MIX_KNOB, 20));   /* MIX, 0-127 */
    const m = ctx.writes.find((x) => x.key === 'mix');
    check(m && parseInt(`${m.val}`, 10) === 60,
          `wide-range acceleration was lost: mix went to ${m && m.val}, expected 60`);
}

/* Every read is a blocking round-trip to the shim serviced once per SPI frame.
 * fetchAll wants ~58 keys; one at a time that is over a second of stall, and it
 * runs from the machine-select handler. It must use the bulk path. */
async function testFetchAllUsesBulkReads() {
    console.log('a full refresh costs a couple of round-trips, not sixty');
    const ctx = await loadUI();
    ctx.host.init();

    ctx.roundTrips.length = 0;
    ctx.host.onMidiMessageInternal(noteOn(PALETTE_ORDER[1]));   /* load a machine */
    ctx.host.onMidiMessageInternal(noteOff(PALETTE_ORDER[1]));

    check(ctx.roundTrips.length > 0, 'loading a machine refreshed nothing');
    check(ctx.roundTrips.length <= 4,
          `a machine change cost ${ctx.roundTrips.length} round-trips — at ~23 ms ` +
          `each that is the "super slow" stall; batch them with get_params`);
    const bulk = ctx.roundTrips.filter((r) => r.bulk).length;
    check(bulk > 0, 'the bulk get_params path was never used');
}

/* The bulk wire format is schwung's, not ours: "<count>\n" then count records
 * of "<len>\n<bytes>". Decode it wrong and every value shifts by one key —
 * which would look like working software right up until a knob edits the wrong
 * parameter. The mock implements the format from the shim's own parser; this
 * proves the UI reads real values back out of it, by nudging a value it could
 * only have got from a bulk response.
 *
 * `machines` is variable-length and sits in the same batch, so a naive decoder
 * that assumed fixed records would land somewhere else entirely. */
async function testBulkDecodeIsPositionallyCorrect() {
    console.log('bulk-read values land on the right keys');
    const seed = { mix: '99' };
    seed[STAGE_KEY[1]] = `${FX_FAMILY[13]}`;
    const ctx = await atGlobalWith(seed);

    ctx.host.onMidiMessageInternal(cc(KNOB1 + 1, 1));       /* FX 1 machine +1 */
    const w = ctx.writes.find((x) => x.key === STAGE_KEY[1]);
    check(w && parseInt(`${w.val}`, 10) === FX_FAMILY[14],
          `the FX 1 machine continued from the wrong base: wrote ${w && w.val}, ` +
          `expected ${FX_FAMILY[14]}`);

    ctx.writes.length = 0;
    ctx.host.onMidiMessageInternal(cc(KNOB1 + MIX_KNOB, 1));   /* mix +1 */
    const m = ctx.writes.find((x) => x.key === 'mix');
    check(m && parseInt(`${m.val}`, 10) === 100,
          `mix continued from the wrong base: wrote ${m && m.val}, expected 100`);
}

/* -------------------------------------------------------- feedback guard */

function withJack(ctx, speakers, lineIn) {
    ctx.host.host_speaker_active = () => speakers;
    ctx.host.host_line_in_connected = () => lineIn;
}

async function testFeedbackGuardArmsOnRisk() {
    console.log('the feedback guard mutes the input when the mic can hear the speakers');
    const ctx = await loadUI();
    ctx.store.hw_input = '1';
    withJack(ctx, true, true);            /* speakers on, but a cable is in */
    ctx.host.init();
    ctx.writes.length = 0;
    for (let i = 0; i < 30; i++) ctx.host.tick();
    check(!ctx.writes.some((w) => w.key === 'monitor' && `${w.val}` === '0'),
          'guard muted with a cable plugged in — that is not a feedback path');

    /* pull the cable: speakers live, mic open */
    withJack(ctx, true, false);
    ctx.writes.length = 0;
    for (let i = 0; i < 30; i++) ctx.host.tick();
    const muted = ctx.writes.find((w) => w.key === 'monitor');
    check(!!muted && `${muted.val}` === '0',
          `guard did not mute on risk; writes were ${JSON.stringify(ctx.writes)}`);

    /* plug back in: it must restore, not stay muted forever */
    withJack(ctx, true, true);
    ctx.writes.length = 0;
    for (let i = 0; i < 30; i++) ctx.host.tick();
    const restored = ctx.writes.find((w) => w.key === 'monitor');
    check(!!restored && `${restored.val}` === '1',
          `guard did not restore the input when the risk cleared (${restored && restored.val})`);
}

async function testGuardSilentForChainBuild() {
    console.log('the guard stays out of the way when the build does not read the mic');
    const ctx = await loadUI();
    ctx.store.hw_input = '0';             /* the audio_fx build */
    withJack(ctx, true, false);           /* would be risky IF it read the mic */
    ctx.host.init();
    ctx.writes.length = 0;
    for (let i = 0; i < 30; i++) ctx.host.tick();
    check(!ctx.writes.some((w) => w.key === 'monitor'),
          'the guard armed for a build that processes upstream chain audio');
}

async function testMonitorManualOverride() {
    console.log('shift + fill overrides the guard');
    const ctx = await loadUI();
    ctx.store.hw_input = '1';
    withJack(ctx, true, false);
    ctx.host.init();
    for (let i = 0; i < 30; i++) ctx.host.tick();

    ctx.writes.length = 0;
    holdShift(ctx, true);
    ctx.host.onMidiMessageInternal(noteOn(69));
    ctx.host.onMidiMessageInternal(noteOff(69));
    holdShift(ctx, false);
    const on = ctx.writes.find((w) => w.key === 'monitor');
    check(!!on && `${on.val}` === '1', `override did not unmute (${on && on.val})`);

    /* and the guard must not immediately stamp on the override */
    ctx.writes.length = 0;
    for (let i = 0; i < 30; i++) ctx.host.tick();
    check(!ctx.writes.some((w) => w.key === 'monitor' && `${w.val}` === '0'),
          'the guard overrode the user while the risk state was unchanged');
}

/* ---------------------------------------------------------------- presets */

const PDIR = '/data/UserData/schwung/presets/overwork';

/* Open the preset browser: Shift + jog click. */
function openPresets(ctx) {
    holdShift(ctx, true);
    ctx.host.onMidiMessageInternal(cc(3, 127));      /* MoveMainButton */
    holdShift(ctx, false);
    ctx.host.tick();                                 /* the device redraws on tick */
}

/* THE guard on the whole approach. If the mock's os.readdir were written from
 * the UI's assumptions — a flat array of filenames — this test would pass
 * against a broken implementation. So assert the mock reproduces the REAL
 * contract, and that the naive reading of it fails the way Mono did. */
async function testReaddirContractIsFaithful() {
    console.log('the os.readdir mock reproduces the real tuple contract');
    const ctx = await loadUI();
    ctx.host.host_ensure_dir(PDIR);
    ctx.host.host_write_file(`${PDIR}/one.json`, '{"name":"One","state":"{}"}');

    const raw = ctx.vfs.readdir(PDIR);
    check(Array.isArray(raw) && Array.isArray(raw[0]),
          'readdir must answer a [names, errno] tuple, got ' + JSON.stringify(raw));
    check(raw[0].includes('.') && raw[0].includes('..'),
          'a real listing includes "." and ".."; mock gave ' + JSON.stringify(raw[0]));
    check(raw[1] === 0, 'errno slot should be 0 on success, got ' + raw[1]);

    /* the naive implementation Mono shipped, run against this same mock */
    const naive = (() => {
        const names = ctx.vfs.readdir(PDIR);      /* treated as a flat array */
        try { return /\.json$/i.test(names) ? [String(names).replace(/\.json$/i, '')] : []; }
        catch (e) { return ['THREW']; }
    })();
    check(naive.length === 0 || naive[0] === 'THREW',
          'the naive flat-array reading should find nothing (or throw) against the ' +
          'real contract — it "found" ' + JSON.stringify(naive) +
          ', so the mock is too forgiving to catch the Mono bug');

    /* os.rename and os.remove must report failure by return code, not throw */
    ctx.vfs.failRenames(true);
    let threw = false;
    let rc = 0;
    try { rc = ctx.vfs.rename(`${PDIR}/one.json`, `${PDIR}/two.json`); }
    catch (e) { threw = true; }
    check(!threw && rc < 0, 'a failing rename must return -errno, not throw');
    ctx.vfs.failRenames(false);
    check(ctx.vfs.remove(`${PDIR}/nope.json`) < 0, 'removing a missing file must return -errno');
}

/* THE bug this feature exists to close: a source-machine preset restored every
 * parameter, LFO, pattern and lock, and then played silence. The audio is not
 * in the patch file — a few seconds of stereo does not fit a 64 KiB blob — so
 * the patch records the PATH and the UI fetches the audio back. */
async function testPresetRestoresItsSample() {
    console.log('loading a preset fetches back the sample it was saved with');
    const dir = '/data/UserData/UserLibrary/Samples';

    /* --- save half: a patch with a sample must record where it came from --- */
    const a = await loadUI();
    a.host.init();
    a.vfs.dirs.add(dir);
    a.vfs.binaries.set(`${dir}/kit.wav`, makeWav({ frames: 600 }));
    check(a.host.loadSampleFile(`${dir}/kit.wav`), 'the fixture sample did not load');
    check(a.store.sample_path === `${dir}/kit.wav`,
          `the engine was told the path was "${a.store.sample_path}"`);

    openPresets(a);
    a.host.onMidiMessageInternal(cc(3, 127));            /* "Save new" */
    const file = [...a.vfs.files.keys()].find((f) => f.endsWith('.json'));
    check(!!file, 'nothing was saved');
    const saved = JSON.parse(a.vfs.files.get(file));
    check(/"smp":"/.test(saved.state),
          `the saved patch does not record its sample: ${saved.state.slice(0, 120)}`);

    /* --- load half: a FRESH session holding nothing, which is what a reboot
     * or someone else's preset actually looks like --- */
    const b = await loadUI();
    b.host.init();
    b.vfs.dirs.add(dir);
    b.vfs.binaries.set(`${dir}/kit.wav`, makeWav({ frames: 600 }));
    b.host.host_module_set_param('sample_clear', '1');
    b.host.host_ensure_dir(PDIR);
    b.host.host_write_file(`${PDIR}/kitpatch.json`, JSON.stringify(saved));

    openPresets(b);
    b.writes.length = 0;
    b.host.onMidiMessageInternal(cc(3, 127));            /* click loads index 1 */

    check(b.writes.some((w) => w.key === 'state'),
          `the click did not load a preset; writes were ${JSON.stringify(b.writes.map((w) => w.key))}`);
    check(b.writes.some((w) => w.key === 'sample_begin'),
          'the preset loaded but never fetched its audio back');
    check(parseInt(b.store.sample_frames, 10) === 600,
          `engine holds ${b.store.sample_frames} frames after the preset load`);
}

/* A preset whose file has moved must say so and leave what is loaded alone.
 * Dropping the current sample would turn "this patch's file moved" into
 * "everything is silent now", which is the worse of the two failures. */
async function testPresetWithAMissingSampleIsSurvivable() {
    console.log('a preset naming a sample that is gone reports it and keeps the old one');
    const ctx = await loadUI();
    ctx.host.init();
    const dir = '/data/UserData/UserLibrary/Samples';
    ctx.vfs.dirs.add(dir);
    ctx.vfs.binaries.set(`${dir}/here.wav`, makeWav({ frames: 500 }));
    check(ctx.host.loadSampleFile(`${dir}/here.wav`), 'the fixture sample did not load');

    ctx.host.host_ensure_dir(PDIR);
    ctx.host.host_write_file(`${PDIR}/gone.json`, JSON.stringify({
        name: 'Gone',
        state: `{"v":1,"mix":64,"smp":"${dir}/vanished.wav"}`
    }));
    openPresets(ctx);
    ctx.host.onMidiMessageInternal(cc(3, 127));          /* click loads index 1 */
    ctx.host.tick();

    check(parseInt(ctx.store.sample_frames, 10) === 500,
          'the missing file wiped the sample that was already loaded');
    const said = ctx.spoken.join(' | ');
    check(/Missing/i.test(said),
          `nothing reported the missing file; it said "${said}"`);
}

async function testPresetSaveThenList() {
    console.log('saving a preset writes a file the browser can then list');
    const ctx = await loadUI();
    ctx.host.init();

    openPresets(ctx);
    ctx.host.onMidiMessageInternal(cc(3, 127));       /* click on "Save new" */

    const written = [...ctx.vfs.files.keys()].filter((f) => f.endsWith('.json'));
    check(written.length === 1, `expected one preset file, got ${JSON.stringify(written)}`);
    check(!written.some((f) => f.endsWith('.tmp')), 'a .tmp file was left behind');

    const payload = JSON.parse(ctx.vfs.files.get(written[0]));
    check(!!payload.state, 'preset carries no state blob');
    check(payload.module === 'overwork', `preset module tag is ${payload.module}`);

    /* the saved preset must now appear in the list — the exact step that
     * silently did nothing in Mono */
    ctx.host.tick();
    const shown = ctx.screen.map((l) => l.text).join(' ');
    check(/Pattern 1/.test(shown),
          `saved preset does not appear in the browser; screen shows: ${shown}`);
}

