/* The engine is the authority. If the transfer is dropped in transit, the UI
 * must NOT report success just because it finished sending. */
async function testLoadTrustsTheEngineNotItself() {
    console.log('a transfer the engine did not take is reported as failed');
    const ctx = await loadUI();
    ctx.host.init();
    ctx.vfs.dirs.add('/data/UserData/UserLibrary/Samples');
    ctx.vfs.binaries.set('/data/UserData/UserLibrary/Samples/a.wav',
                         makeWav({ frames: 1000 }));

    /* The engine refuses everything: sample_end commits nothing. This is the
     * transfer being dropped in transit, which the UI can only detect by
     * asking rather than assuming. */
    const realSet = ctx.host.host_module_set_param;
    ctx.host.host_module_set_param = (k, v) => {
        realSet(k, v);
        if (k === 'sample_end') { ctx.store.sample_frames = '0'; ctx.store.sample_name = ''; }
    };

    holdShift(ctx, true);
    ctx.host.onMidiMessageInternal(noteOn(70));
    ctx.host.onMidiMessageInternal(noteOff(70));
    holdShift(ctx, false);
    const ok = ctx.host.loadSampleFile('/data/UserData/UserLibrary/Samples/a.wav');
    check(ok === false, 'the UI reported success while the engine held nothing');
    ctx.host.tick();
    const screen = ctx.screen.map((x) => x.text).join(' ');
    check(/failed/i.test(screen), `no failure shown; screen was "${screen}"`);
}


/* Leaving the browser open after a successful load left every pad inert with
 * no sign why — reported from hardware as the machine palette not working,
 * when in fact the browser was still swallowing input. */
async function testLoadClosesTheBrowserAndPadsWorkAgain() {
    console.log('a successful load closes the browser and returns the pads');
    const ctx = await loadUI();
    ctx.host.init();
    ctx.vfs.dirs.add('/data/UserData/UserLibrary/Samples');
    ctx.vfs.binaries.set('/data/UserData/UserLibrary/Samples/kick.wav',
                         makeWav({ frames: 4410 }));

    holdShift(ctx, true);
    ctx.host.onMidiMessageInternal(noteOn(70));
    ctx.host.onMidiMessageInternal(noteOff(70));
    holdShift(ctx, false);
    ctx.host.onMidiMessageInternal(cc(JOG_CLICK, 127));
    ctx.host.tick();

    const screen = ctx.screen.map((x) => x.text).join(' ');
    check(!/SAMPLES/.test(screen),
          `the browser stayed open after loading; screen was "${screen}"`);
    check(/Loaded/.test(screen),
          `the confirmation vanished with the browser; screen was "${screen}"`);

    /* and the palette works again — this is the reported symptom. One Shot is
     * a source, so it now sits at its position in the SRC family rather than
     * behind a Shift bank. */
    ctx.writes.length = 0;
    const oneShot = SRC_FAMILY.indexOf(21);
    ctx.host.onMidiMessageInternal(noteOn(PALETTE_ORDER[oneShot]));
    ctx.host.onMidiMessageInternal(noteOff(PALETTE_ORDER[oneShot]));
    const loaded = ctx.writes.find((w) => STAGE_KEY.indexOf(w.key) >= 0);
    check(loaded && parseInt(`${loaded.val}`, 10) === 21,
          `the One Shot palette pad loaded ${loaded && loaded.val}, expected 21 ` +
          `— the pads are still locked out`);
}

/* A FAILED load must keep the browser open: the next thing you want is
 * another file, not to be thrown back to the sequencer. */
async function testFailedLoadKeepsTheBrowserOpen() {
    console.log('a failed load leaves the browser open to try another file');
    const ctx = await loadUI();
    ctx.host.init();
    ctx.vfs.dirs.add('/data/UserData/UserLibrary/Samples');
    ctx.vfs.binaries.set('/data/UserData/UserLibrary/Samples/bad.wav',
                         Buffer.from('not a wav'));

    holdShift(ctx, true);
    ctx.host.onMidiMessageInternal(noteOn(70));
    ctx.host.onMidiMessageInternal(noteOff(70));
    holdShift(ctx, false);
    ctx.host.onMidiMessageInternal(cc(JOG_CLICK, 127));
    ctx.host.tick();

    const screen = ctx.screen.map((x) => x.text).join(' ');
    check(/SAMPLES/.test(screen),
          `the browser closed on a failed load; screen was "${screen}"`);
}


/* Hardware, 2026-07-29: a sysex dump streamed through the MIDI_IN ring and
 * reached this handler as a burst of bytes reinterpreted as three-byte
 * messages — status 240, then 29, 58, 178, then 247 — after which the stream
 * degraded to an endless run of status=0 d1=0 d2=0. Thousands arrived. The
 * module ran without the house noise filter, so all of it was processed. */
async function testGarbageMidiIsIgnored() {
    console.log('sysex, clock and misaligned bytes never reach the surface');
    const ctx = await loadUI();
    ctx.host.init();
    ctx.host.tick();
    const before = ctx.screen.map((x) => x.text).join(' ');
    ctx.writes.length = 0;

    /* the exact stream captured from the device */
    const garbage = [
        [178, 0, 77], [240, 0, 33], [29, 1, 1], [58, 0, 77], [0, 247, 0],
        [0xF8, 0, 0], [0xD0, 64, 0], [0xA0, 60, 100], [0x90, 3, 100]
    ];
    for (let i = 0; i < 200; i++) {
        for (const g of garbage) ctx.host.onMidiMessageInternal(g);
        ctx.host.onMidiMessageInternal([0, 0, 0]);
    }
    ctx.host.tick();

    check(ctx.writes.length === 0,
          `garbage MIDI wrote ${ctx.writes.length} parameters: ` +
          JSON.stringify(ctx.writes.slice(0, 4)));
    check(ctx.screen.map((x) => x.text).join(' ') === before,
          'garbage MIDI changed what is on screen');
}

/* ...and real input must still get through the new guard. */
async function testRealInputStillWorksThroughTheFilter() {
    console.log('real pad and knob input survives the noise filter');
    const ctx = await loadUI();
    ctx.host.init();
    await gotoGlobalPage(ctx);
    ctx.writes.length = 0;
    ctx.host.onMidiMessageInternal(cc(KNOB1, 1));
    check(ctx.writes.some((w) => w.key === STAGE_KEY[0]),
          'the filter swallowed a real knob turn');

    ctx.writes.length = 0;
    ctx.host.onMidiMessageInternal(noteOn(PALETTE_ORDER[1]));
    ctx.host.onMidiMessageInternal(noteOff(PALETTE_ORDER[1]));
    check(ctx.writes.length > 0, 'the filter swallowed a real pad press');
}


/* Move's step buttons are NOTES 16-31. This handler lived in the CC branch,
 * so on hardware nothing reached it: the sequencer could not be played from
 * the surface at all, and the note fell through to the engine which fired the
 * sample. Every step check passed because the harness sent CCs too. */
async function testStepsArriveAsNotes() {
    console.log('step buttons work as notes, the way the hardware sends them');
    const ctx = await loadUI();
    ctx.host.init();

    /* the exact message the device logs: status=144 d1=20 d2=127 */
    ctx.writes.length = 0;
    ctx.host.onMidiMessageInternal([0x90, 20, 127]);
    ctx.host.onMidiMessageInternal([0x90, 20, 0]);
    const toggled = ctx.writes.find((w) => /^step\d+$/.test(w.key));
    check(!!toggled, `a step note toggled no trig; wrote ${JSON.stringify(ctx.writes)}`);
    check(toggled && toggled.key === 'step4',
          `note 20 toggled ${toggled && toggled.key}, expected step4 (20 - 16)`);

    /* and the p-lock gesture, which is the whole point of the module */
    ctx.writes.length = 0;
    ctx.host.onMidiMessageInternal([0x90, 16, 127]);      /* hold step 1 */
    ctx.host.onMidiMessageInternal(cc(KNOB1, 3));         /* turn a knob  */
    ctx.host.onMidiMessageInternal([0x90, 16, 0]);        /* release      */
    const locked = ctx.writes.find((w) => /^lock\d+_\d+$/.test(w.key));
    check(!!locked,
          `hold-step + knob wrote no lock; got ${JSON.stringify(ctx.writes)}`);
}


/* The launch gesture is itself a Shift combo (Shift+Vol+jog click), and
 * shadow_ui does not forward MIDI to a module until init() has returned —
 * measured at about six seconds. The release therefore lands inside that
 * window and is discarded, so a module that trusts its own CC 49 tracking
 * starts life believing Shift is held, forever.
 *
 * On hardware that did not look like one bug. It looked like several: knobs
 * edited base values instead of writing locks, palette pads loaded machine+21,
 * and the slot pad opened the sample browser. All reported separately. */
async function testShiftDoesNotLatchFromTheLaunchGesture() {
    console.log('a shift-on with no release does not latch the module');
    const ctx = await loadUI();
    ctx.host.init();

    /* the press arrives, the release never does */
    ctx.host.setShift(1);
    ctx.host.onMidiMessageInternal(cc(SHIFT, 127));
    for (let i = 0; i < 60; i++) ctx.host.tick();

    /* a knob must now write a LOCK, not edit the base — which is the whole
     * gesture the module exists for */
    ctx.writes.length = 0;
    ctx.host.onMidiMessageInternal(stepDown(0));
    ctx.host.onMidiMessageInternal(cc(KNOB1, 4));
    ctx.host.onMidiMessageInternal(stepUp(0));
    const locked = ctx.writes.find((w) => /^lock\d+_\d+$/.test(w.key));
    check(!!locked,
          `Shift stayed latched from launch: hold-step + knob wrote ` +
          `${JSON.stringify(ctx.writes)} instead of a lock`);
}

